const app=document.querySelector('#app'),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>v==null?'—':Number(v).toFixed(1); function notice(message){let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';n.className='notice';document.body.appendChild(n)}n.innerHTML=`<div><b>Information</b><p>${esc(message)}</p><button onclick="this.closest('.notice').remove()">Fermer</button></div>`} const api=(p,o={})=>fetch(p,{headers:{'Content-Type':'application/json'},...o}).then(async r=>{let x=await r.json();if(!r.ok)throw Error(x.error||'Action impossible.');return x}); window.addEventListener('unhandledrejection',e=>{e.preventDefault();notice(e.reason?.message||'Action impossible. Veuillez réessayer.');}); window.addEventListener('error',e=>{if(e.message)notice('Une action ne peut pas être réalisée : '+e.message)});let T=[],S=[];
async function load(){[T,S]=await Promise.all([api('/api/templates'),api('/api/sessions')]);home()};const back='<button class="secondary" onclick="load()">← Retour</button>';
function home(){app.innerHTML=`<section class="card"><h2>Questionnaires / modèles</h2><button onclick="createModel()">Créer</button> <a href="/api/templates/matrix.xlsx"><button type="button" class="secondary">Télécharger une matrice vierge</button></a> <button class="secondary" onclick="importer()">Importer matrice</button> <button class="secondary" onclick="models()">Gérer les configurations</button><p class="muted">EPC/SENEVAL est un modèle disponible.</p></section><section class="card"><h2>Sessions d’atelier</h2><button onclick="newSession()">Créer une session</button>${S.map(s=>`<div class="row"><b>${esc(s.name)}</b><button onclick="moderator('${s.id}')">Ouvrir</button></div>`).join('')||'<p>Aucune session.</p>'}</section>`}
function createModel(){app.innerHTML=`<section class="card">${back}<h2>Nouveau questionnaire</h2><form onsubmit="makeModel(event)"><label>Nom du questionnaire<input name="name" required></label><h3>Échelle de notation</h3>${[[5,'Totalement d’accord'],[4,'D’accord'],[3,'Neutre'],[2,'N’est pas d’accord'],[1,'Totalement en désaccord']].map(x=>`<label>${x[0]}<input name="note${x[0]}" value="${x[1]}"></label>`).join('')}<button>Enregistrer</button></form></section>`};async function makeModel(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),x=await api('/api/templates',{method:'POST',body:JSON.stringify({name:f.name})});window.model=await api('/api/templates/'+x.id);window.model.scale.labels={1:f.note1,2:f.note2,3:f.note3,4:f.note4,5:f.note5};await api('/api/templates/'+x.id,{method:'PUT',body:JSON.stringify({name:f.name,description:'',scale:window.model.scale,priority:window.model.priority})});edit(x.id)}
function models(){app.innerHTML=`<section class="card">${back}<h2>Configurations</h2>${T.map(t=>`<div class="row"><span><b>${esc(t.name)}</b> · v${t.version}</span><button onclick="edit('${t.id}')">Ouvrir</button><button class="secondary" onclick="dup('${t.id}')">Dupliquer</button><a href="/api/templates/${t.id}/matrix.xlsx"><button type="button" class="secondary">Exporter XLSX</button></a><button class="danger" onclick="removeModel('${t.id}','${esc(t.name)}')">Supprimer</button></div>`).join('')}</section>`};async function dup(id){let x=await api('/api/templates/'+id+'/clone',{method:'POST',body:'{}'});edit(x.id)};async function edit(id){window.model=await api('/api/templates/'+id);renderModel()};async function removeModel(id,name){if(!confirm('Supprimer le questionnaire "'+name+'" ?\n\nCette action supprimera cette configuration si elle n’est utilisée par aucune session.'))return;try{await api('/api/templates/'+id,{method:'DELETE'});await load()}catch(e){if(confirm(e.message+'\n\nVoulez-vous le retirer de la liste des modèles tout en conservant les sessions historiques ?')){await api('/api/templates/'+id+'?force=1',{method:'DELETE'});await load()}}}
function renderModel(){let t=window.model;let ready=t.domains.some(d=>d.active&&d.indicators.some(i=>i.active));app.innerHTML=`<section class="card">${back}<h2>QUESTIONNAIRE : ${esc(t.name)}</h2><h3>Échelle</h3>${[5,4,3,2,1].map(n=>`<div>${n} — ${esc(t.scale.labels?.[n]||'')}</div>`).join('')}<hr>${t.domains.map(d=>`<section class="domain"><h3>${esc(d.label)}</h3><div class="row"><button class="secondary" onclick="editDomainForm('${d.id}')">Modifier le nom</button><button class="secondary" onclick="moveDomain('${d.id}',-1)">↑</button><button class="secondary" onclick="moveDomain('${d.id}',1)">↓</button></div>${d.indicators.filter(i=>i.active).map((i,n)=>`<div class="indicator"><b>${n+1}. ${esc(i.label)}</b><br>${esc(i.description)}<div class="row"><button class="secondary" onclick="indicator('${d.id}','${i.id}')">Modifier</button><button class="danger" onclick="del('${i.id}')">Supprimer</button><button class="secondary" onclick="moveIndicator('${i.id}',-1)">↑</button><button class="secondary" onclick="moveIndicator('${i.id}',1)">↓</button></div></div>`).join('')}<button onclick="indicator('${d.id}')">+ Ajouter une référence / question</button></section>`).join('')}<button onclick="editDomainForm()">+ Ajouter un domaine</button><hr><button ${ready?'':'disabled'} onclick="newSession('${t.id}')">Valider le questionnaire et démarrer un atelier →</button>${ready?'':'<p class="muted">Ajoutez au moins un domaine avec une question pour démarrer un atelier.</p>'}</section>`}
async function saveModel(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),t=window.model,labels;try{labels=JSON.parse(f.labels||'{}')}catch(_){return alert('Les libellés doivent être un JSON valide.')}let x=await api('/api/templates/'+t.id,{method:'PUT',body:JSON.stringify({name:f.name,description:f.description,scale:{type:'numeric',min:+f.min,max:+f.max,labels},priority:t.priority})});if(x.versionCreated)alert('Nouvelle version créée.');await edit(x.id)}
function editDomainForm(id){let d=window.model.domains.find(x=>x.id===id)||{};app.innerHTML=`<section class="card"><button class="secondary" onclick="renderModel()">← Retour</button><h2>${id?'Modifier le domaine':'Ajouter un domaine'}</h2><form onsubmit="saveDomain(event,'${id||''}')"><label>Nom du domaine<input name="label" required value="${esc(d.label||'')}"></label><button class="secondary" type="button" onclick="renderModel()">Annuler</button><button>${id?'Enregistrer':'Ajouter'}</button></form></section>`};async function saveDomain(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(!f.label.trim())return alert('Veuillez donner un nom au domaine.');if(id){let d=window.model.domains.find(x=>x.id===id);await api('/api/domains/'+id,{method:'PUT',body:JSON.stringify({label:f.label,description:d.description,displayOrder:d.display_order,active:true})})}else await api('/api/templates/'+window.model.id+'/domains',{method:'POST',body:JSON.stringify({label:f.label})});edit(window.model.id)}
function indicator(did,iid){let i=window.model.domains.flatMap(d=>d.indicators).find(x=>x.id===iid)||{domainId:did};app.innerHTML=`<section class="card"><button class="secondary" onclick="renderModel()">← Retour</button><h2>${iid?'Modifier la question':'Ajouter une référence / question'}</h2><form onsubmit="saveIndicator(event,'${iid||''}')"><input type="hidden" name="domainId" value="${i.domainId}"><label>Référence<input name="label" required value="${esc(i.label||'')}"></label><label>Indicateur qualitatif ou Capacité<textarea name="description" required>${esc(i.description||'')}</textarea></label><button class="secondary" type="button" onclick="renderModel()">Annuler</button><button>${iid?'Enregistrer':'Ajouter'}</button></form></section>`};async function saveIndicator(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),i=window.model.domains.flatMap(d=>d.indicators).find(x=>x.id===id)||{domainId:f.domainId};if(!f.label.trim()||!f.description.trim())return notice('Veuillez renseigner la référence et la question.');let d={domainId:i.domainId,code:i.code||'',label:f.label,description:f.description,responseType:'numeric',required:true,active:true,displayOrder:i.display_order||1};if(id)await api('/api/indicators/'+id,{method:'PUT',body:JSON.stringify(d)});else await api('/api/domains/'+i.domainId+'/indicators',{method:'POST',body:JSON.stringify(d)});edit(window.model.id)};async function del(id){if(confirm('Supprimer cette question ?')){await api('/api/indicators/'+id,{method:'DELETE'});edit(window.model.id)}}
async function moveDomain(id,delta){let a=window.model.domains,b=a.findIndex(x=>x.id===id),o=a[b+delta];if(!o)return;let x=a[b];await api('/api/domains/'+x.id,{method:'PUT',body:JSON.stringify({label:x.label,description:x.description,displayOrder:o.display_order,active:true})});await api('/api/domains/'+o.id,{method:'PUT',body:JSON.stringify({label:o.label,description:o.description,displayOrder:x.display_order,active:true})});edit(window.model.id)}
async function moveIndicator(id,delta){let d=window.model.domains.find(x=>x.indicators.some(i=>i.id===id)),a=d.indicators.filter(i=>i.active),b=a.findIndex(x=>x.id===id),o=a[b+delta];if(!o)return;let x=a[b],put=i=>api('/api/indicators/'+i.id,{method:'PUT',body:JSON.stringify({domainId:d.id,code:i.code,label:i.label,description:i.description,responseType:i.response_type,required:i.required,active:true,displayOrder:i.display_order})});let xo=x.display_order;x.display_order=o.display_order;o.display_order=xo;await put(x);await put(o);edit(window.model.id)}
function importer(){app.innerHTML=`<section class="card">${back}<h2>Importer une matrice XLSX</h2><form onsubmit="up(event)"><input type="file" name="f" accept=".xlsx" required><button>Contrôler et prévisualiser</button></form></section>`};async function up(e){e.preventDefault();let r=await fetch('/api/templates/import/preview',{method:'POST',body:new FormData(e.target)}),x=await r.json();if(!r.ok)return alert(x.error);app.innerHTML=`<section class="card">${back}<h2>Aperçu</h2>${x.errors.length?`<p class="error">${x.errors.join('<br>')}</p>`:`<p class="ok">${x.rows} indicateurs valides ; rien n’est enregistré.</p>`}<button ${x.errors.length?'disabled':''} onclick="confirmImport('${x.token}')">Valider l’import</button></section>`};async function confirmImport(token){let x=await api('/api/templates/import/confirm',{method:'POST',body:JSON.stringify({token})});edit(x.id)}
function newSession(selectedId){app.innerHTML=`<section class="card">${back}<h2>Nouvel atelier</h2><form onsubmit="makeSession(event)"><label>Questionnaire<select name="templateId">${T.map(t=>`<option value="${t.id}" ${t.id===selectedId?'selected':''}>${esc(t.name)} v${t.version}</option>`)}</select></label><label>Nom de l’atelier<input name="name" required></label><button>Créer et ouvrir l’atelier →</button></form></section>`};async function makeSession(e){e.preventDefault();let x=await api('/api/sessions',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});moderator(x.id)}
async function moderator(id){let a=await api('/api/sessions/'+id+'/analysis'),link=location.origin+'/?session='+id;app.innerHTML=`<section class="card">${back}<h2>${esc(a.session.name)}</h2><div class="row"><button onclick="diagnostic('${id}')">Diagnostic</button><button class="secondary" onclick="preview('${id}')">Prévisualiser participant</button></div><hr><h3>Collecte</h3><code>${esc(link)}</code><div class="row"><button onclick="navigator.clipboard.writeText('${link}').then(()=>notice('Lien copié.')).catch(()=>notice('Copie impossible : sélectionnez le lien.'))">Copier le lien</button><button onclick="join('${id}')">Ouvrir participant</button><button onclick="qr('${link}')">QR code</button></div><p>Participants : <b>${a.participantCount}</b> · Questionnaires validés : <b>${a.completedCount}</b></p></section>`}
const level=v=>v==null?'—':v<20?'':v<=39?'Loin en dessous de la moyenne':v<=59?'En dessous de la moyenne':v<=70?'Moyen':v<=80?'Au-dessus de la moyenne':'Bien au-dessus de la moyenne';
function bars(ds,grad=false){let a=ds.filter(d=>d.capacity!=null);if(!a.length)return '<p class="muted">Pas encore de données disponibles.</p>';return `<svg class="chart" viewBox="0 0 760 ${70+a.length*46}"><text x="180" y="16" fill="#176b4b">■ Capacité</text><text x="290" y="16" fill="#536271">■ Consensus</text>${a.map((d,n)=>{let y=35+n*46,c=grad?d.gradedCapacity:d.capacity,s=grad?d.gradedConsensus:d.consensus;return `<text x="2" y="${y+12}" font-size="11">${esc(d.label).slice(0,22)}</text><rect x="180" y="${y}" width="${(c||0)*5}" height="15" fill="#176b4b"/><rect x="180" y="${y+18}" width="${(s||0)*5}" height="15" fill="#536271"/><text x="${185+(c||0)*5}" y="${y+12}" font-size="10">${fmt(c)}</text><text x="${185+(s||0)*5}" y="${y+30}" font-size="10">${fmt(s)}</text>`}).join('')}</svg>`}
function radar(ds){let a=ds.filter(d=>d.capacity!=null),n=a.length;if(!n)return '<p class="muted">Pas encore de données disponibles.</p>';let cx=250,cy=235,r=170,p=(v,i)=>{let z=-Math.PI/2+i*2*Math.PI/n;return `${cx+Math.cos(z)*r*v/100},${cy+Math.sin(z)*r*v/100}`};return `<svg class="chart" viewBox="0 0 500 470"><text x="12" y="18" fill="#176b4b">■ Capacité</text><text x="120" y="18" fill="#536271">■ Consensus</text>${a.map((d,i)=>{let z=-Math.PI/2+i*2*Math.PI/n;return `<line x1="${cx}" y1="${cy}" x2="${cx+Math.cos(z)*r}" y2="${cy+Math.sin(z)*r}" stroke="#aab"/><text x="${cx+Math.cos(z)*(r+12)}" y="${cy+Math.sin(z)*(r+12)}" font-size="10">${esc(d.code||d.label).slice(0,9)}</text>`}).join('')}<polygon points="${a.map((d,i)=>p(d.capacity||0,i)).join(' ')}" fill="#176b4b55" stroke="#176b4b" stroke-width="3"/><polygon points="${a.map((d,i)=>p(d.consensus||0,i)).join(' ')}" fill="#53627144" stroke="#536271" stroke-width="3"/></svg>`}
function visual(ds){return `<section class="graphs"><h3>Radar global</h3>${radar(ds)}<h3>Histogramme standardisé</h3>${bars(ds)}<h3>Histogramme gradué</h3>${bars(ds,true)}<div class="legend">20–39 : Loin en dessous · 40–59 : En dessous · 60–70 : Moyen · 71–80 : Au-dessus · 81–100 : Bien au-dessus</div></section>`}
async function diagnostic(id){let a=await api('/api/sessions/'+id+'/analysis'),w=await api('/api/sessions/'+id+'/workshop-data'),g=a.global;app.innerHTML=`<section class="card"><button class="secondary" onclick="moderator('${id}')">← Retour</button><h2>Diagnostic — ${esc(a.session.name)}</h2><p>Participants ${a.participantCount} · validés ${a.completedCount} · taux ${a.participantCount?Math.round(a.completedCount/a.participantCount*100):0}%</p><div class="grid"><div class="metric">Capacité standardisée <b>${fmt(g.capacity)}</b></div><div class="metric">Consensus standardisé <b>${fmt(g.consensus)}</b></div><div class="metric">Capacité graduée <b>${g.gradedCapacity??'—'}</b></div><div class="metric">Consensus gradué <b>${g.gradedConsensus??'—'}</b></div></div><h3>Synthèse par domaine</h3><table><tr><th>Domaine</th><th>Capacité</th><th>Consensus</th><th>Graduées</th><th>Niveau</th><th>Réponses</th><th></th></tr>${a.domains.map(d=>`<tr><td>${esc(d.label)}</td><td>${fmt(d.capacity)}</td><td>${fmt(d.consensus)}</td><td>${d.gradedCapacity??'—'} / ${d.gradedConsensus??'—'}</td><td>${level(d.capacity)}</td><td>${d.responses}</td><td><button onclick="domainDiagnostic('${id}','${d.id}')">Détail</button></td></tr>`).join('')}</table><h3>Priorités retenues</h3>${w.priorities.length||'Aucune priorité sélectionnée.'}<p><button onclick="finalSummary('${id}')">Synthèse finale</button></p></section>`}
async function domainDiagnostic(sid,did){let a=await api('/api/sessions/'+sid+'/analysis'),w=await api('/api/sessions/'+sid+'/workshop-data'),d=a.domains.find(x=>x.id===did),max=(await api('/api/templates/'+a.session.template_id)).priority.maxPerDomain;let selected=new Set(w.priorities.filter(p=>p.domain_id===did).map(p=>p.indicator_id));app.innerHTML=`<section class="card"><button class="secondary" onclick="diagnostic('${sid}')">← Retour</button><h2>${esc(d.label)}</h2><p>Sélectionnez jusqu’à ${max} priorités : la décision reste humaine.</p><table><tr><th># / Référence</th><th>Capacité</th><th>Consensus</th><th>Distribution</th><th></th></tr>${[...d.indicators].sort((x,y)=>(x.capacity??999)-(y.capacity??999)).map((i,n)=>`<tr><td>${n+1}. ${esc(i.label)}</td><td>${fmt(i.capacity)}</td><td>${fmt(i.consensus)}</td><td>${Object.entries(i.distribution).map(x=>x.join(':')).join(' ')}</td><td>${selected.has(i.id)?`<button class="secondary" onclick="removePriority('${sid}','${did}','${i.id}')">Retirer</button>`:`<button onclick="addPriority('${sid}','${did}','${i.id}',${max},${selected.size})">Sélectionner</button>`}</td></tr>`).join('')}</table><h3>Causes et recommandations</h3><form onsubmit="addCause(event,'${sid}')"><input type="hidden" name="indicatorId" value=""><label>Élément d’analyse<select name="kind"><option>Cause</option><option>Cause racine potentielle</option><option>Symptôme</option><option>Facteur externe</option><option>Hypothèse</option><option>Conséquence</option><option>Levier</option></select></label><textarea name="content" required></textarea><label>Validé par le groupe<select name="validationStatus"><option value="HYPOTHESE">Non</option><option value="FAIT_VALIDE">Oui</option></select></label><button>Ajouter</button></form><form onsubmit="addRecommendation(event,'${sid}')"><h4>Recommandation</h4><input name="title" placeholder="Titre" required><textarea name="description" placeholder="Description"></textarea><select name="kind"><option value="action">Action</option><option value="formation">Formation</option><option value="organisation">Organisation</option><option value="gouvernance">Gouvernance</option><option value="autre">Autre</option></select><input name="owner" placeholder="Responsable (facultatif)"><input name="horizon" placeholder="Horizon (facultatif)"><button>Ajouter recommandation</button></form></section>`}
async function addPriority(s,d,i,max,count){if(count>=max)return notice('Le nombre maximum de priorités pour ce domaine est atteint. Retirez d’abord une priorité.');await api('/api/sessions/'+s+'/priorities',{method:'POST',body:JSON.stringify({domainId:d,indicatorId:i,votes:1})});domainDiagnostic(s,d)};async function removePriority(s,d,i){await api('/api/sessions/'+s+'/priorities/'+i,{method:'DELETE'});domainDiagnostic(s,d)};async function addCause(e,s){e.preventDefault();await api('/api/sessions/'+s+'/analysis-notes',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});notice('Élément d’analyse enregistré.');e.target.reset()};async function addRecommendation(e,s){e.preventDefault();await api('/api/sessions/'+s+'/recommendations',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});notice('Recommandation enregistrée.');e.target.reset()};async function finalSummary(s){let a=await api('/api/sessions/'+s+'/analysis'),w=await api('/api/sessions/'+s+'/workshop-data');app.innerHTML=`<section class="card"><button class="secondary" onclick="diagnostic('${s}')">← Retour</button><h2>Synthèse finale</h2><p>Capacité ${fmt(a.global.capacity)} · consensus ${fmt(a.global.consensus)}</p><h3>Domaines les plus faibles</h3>${a.domains.slice().sort((x,y)=>x.capacity-y.capacity).map(d=>`<p>${esc(d.label)} — ${fmt(d.capacity)}</p>`).join('')}<h3>Priorités</h3><p>${w.priorities.length}</p><h3>Causes validées</h3>${w.notes.filter(n=>n.validation_status==='FAIT_VALIDE').map(n=>`<p>${esc(n.content)}</p>`).join('')||'<p>Aucune.</p>'}<h3>Recommandations</h3>${w.recommendations.map(r=>`<p><b>${esc(r.title)}</b> — ${esc(r.description)}</p>`).join('')||'<p>Aucune.</p>'}<button onclick="window.print()">Imprimer</button></section>`}
function qr(link){app.innerHTML=`<section class="card">${back}<h2>QR code</h2><p class="muted">Projection locale ; lien non accessible depuis un téléphone.</p><div class="qr"><svg viewBox="0 0 29 29">${Array.from({length:29},(_,y)=>Array.from({length:29},(_,x)=>((x*x+y*y+x*y+link.charCodeAt((x+y)%link.length))%4===0)?`<rect x="${x}" y="${y}" width="1" height="1"/>`:'' ).join('')).join('')}</svg></div><code>${esc(link)}</code></section>`}
async function preview(sid){let a=await api('/api/sessions/'+sid+'/analysis'),t=await api('/api/templates/'+a.session.template_id);page(sid,null,t,a.session,{},0,true)};async function join(sid){let p=await api('/api/sessions/'+sid+'/participants',{method:'POST',body:'{}'});let d=await api('/api/participant?session='+sid+'&participant='+p.id);page(sid,p.id,d.template,d.session,d.responses,0,false)}
function page(sid,pid,t,s,r,n,pre){let ds=t.domains.map(d=>({...d,indicators:d.indicators.filter(i=>i.active)})).filter(d=>d.indicators.length),d=ds[n],all=ds.flatMap(x=>x.indicators);if(!d)return notice('Impossible de continuer : ce questionnaire ne contient aucune question active.');window.ctx={sid,pid,t,s,r,n,pre};app.innerHTML=`<section class="card">${pre?`<p class="preview">MODE PRÉVISUALISATION</p><button class="secondary" onclick="moderator('${sid}')">← Retour au modérateur</button>`:''}<h2>${esc(s.name)}</h2><p><b>${esc(d.label)}</b> · Domaine ${n+1} / ${ds.length} · progression ${all.filter(i=>r[i.id]!==undefined).length}/${all.length}</p>${d.indicators.map(i=>`<div class="indicator"><label>${esc(i.label)}${i.required?' *':''}</label>${field(i,r[i.id],pre)}</div>`).join('')}<div class="row">${n?'<button class="secondary" onclick="nav(-1)">← Précédent</button>':'<button class="secondary" onclick="load()">← Retour à l’accueil</button>'}${n<ds.length-1?'<button onclick="nav(1)">Domaine suivant →</button>':`<button onclick="${pre?`moderator('${sid}')`:'finish()'}">${pre?'← Retour au modérateur':'Valider le questionnaire'}</button>`}</div></section>`}
function field(i,v,pre){if(i.response_type==='numeric'){let a=Array.from({length:+ctx.t.scale.max-+ctx.t.scale.min+1},(_,n)=>+ctx.t.scale.min+n);return `<select onchange="answer('${i.id}',this.value,'numeric')"><option></option>${a.map(x=>`<option ${String(x)===String(v)?'selected':''}>${x}</option>`)}</select>`}return `<input value="${esc(v||'')}" onchange="answer('${i.id}',this.value,'${i.response_type}')">`};function answer(i,v,type){ctx.r[i]=type==='numeric'?+v:v;if(!ctx.pre)api('/api/sessions/'+ctx.sid+'/responses',{method:'POST',body:JSON.stringify({participantId:ctx.pid,indicatorId:i,value:ctx.r[i],valueType:type})})};function nav(d){page(ctx.sid,ctx.pid,ctx.t,ctx.s,ctx.r,ctx.n+d,ctx.pre)};async function finish(){await api('/api/sessions/'+ctx.sid+'/complete',{method:'POST',body:JSON.stringify({participantId:ctx.pid})});app.innerHTML=`<section class="card"><h2>Questionnaire validé</h2><p>Vos réponses ont été enregistrées.</p><button onclick="moderator('${ctx.sid}')">← Retour à l’atelier</button></section>`}
let q=new URLSearchParams(location.search);q.get('session')?join(q.get('session')):load();
const diagnosticBase=diagnostic;diagnostic=async id=>{await diagnosticBase(id);let a=await api('/api/sessions/'+id+'/analysis');app.querySelector('.grid')?.insertAdjacentHTML('afterend',visual(a.domains))};
const domainDiagnosticBase=domainDiagnostic;domainDiagnostic=async(sid,did)=>{await domainDiagnosticBase(sid,did);let a=await api('/api/sessions/'+sid+'/analysis'),d=a.domains.find(x=>x.id===did);app.querySelector('table')?.insertAdjacentHTML('beforebegin',`<h3>Graphique des indicateurs</h3>${bars(d.indicators)}`)};
function cohort(ds){let a=ds.filter(d=>d.capacity!=null),cap=a.reduce((x,d)=>x+(d.gradedCapacity??0),0)/(a.length||1),cons=a.reduce((x,d)=>x+(d.gradedConsensus??0),0)/(a.length||1);return {a,cap,cons}}
function graduatedGrid(ds){let q=cohort(ds),pt=(x,y)=>`${70+x*3.8},${350-y*3}`;return `<h3>GRILLE Graduée</h3><svg class="chart" viewBox="0 0 500 390"><rect x="70" y="50" width="380" height="300" fill="#bbb" stroke="#000"/><line x1="260" y1="50" x2="260" y2="350" stroke="#333"/><line x1="70" y1="200" x2="450" y2="200" stroke="#333"/><text x="70" y="35">Organisationnal Capacities</text><text x="180" y="382">Capacité</text><text x="18" y="215" transform="rotate(-90 18 215)">Consensus</text><text x="78" y="72" font-size="10">Faible capacité / consensus élevé</text><text x="330" y="72" font-size="10">Capacité élevée / consensus élevé</text><text x="78" y="335" font-size="10">Faible capacité / consensus faible</text><text x="325" y="335" font-size="10">Capacité élevée / consensus faible</text>${q.a.map(d=>`<circle class="graphbar" data-detail="${esc(d.label)} | Capacité ${fmt(d.capacity)} | Consensus ${fmt(d.consensus)}" cx="${70+d.capacity*3.8}" cy="${350-d.consensus*3}" r="5" fill="#000080"/><text x="${76+d.capacity*3.8}" y="${346-d.consensus*3}" font-size="11">${esc(d.code)}</text>`).join('')}<rect x="${70+(q.a.reduce((x,d)=>x+d.capacity,0)/q.a.length)*3.8-4}" y="${350-(q.a.reduce((x,d)=>x+d.consensus,0)/q.a.length)*3-4}" width="8" height="8" fill="#000"/><text x="8" y="355">0</text><text x="245" y="365">50</text><text x="435" y="365">100</text></svg>`}
function cohortChart(ds){let q=cohort(ds),a=[...q.a,{label:'Moyen',code:'Moyen',gradedCapacity:q.cap,gradedConsensus:q.cons}],w=760,h=390,b=500/(a.length||1),base=315;return `<h3>Notes graduées et moyennes de la cohorte</h3><svg class="chart" viewBox="0 0 ${w} ${h}"><text x="180" y="18" fill="#96305e">■ Capacity Score</text><text x="315" y="18" fill="#7777dd">■ Consensus Score</text><text x="470" y="18" fill="#a00">━ Cohort Cap Mean</text><text x="620" y="18" fill="#00f">━ Cohort Cons Mean</text><line x1="70" y1="${base-q.cap*2.6}" x2="650" y2="${base-q.cap*2.6}" stroke="#a00" stroke-width="3"/><line x1="70" y1="${base-q.cons*2.6}" x2="650" y2="${base-q.cons*2.6}" stroke="#00f" stroke-width="3"/>${a.map((d,i)=>{let x=80+i*b;return `<rect class="graphbar" data-detail="${esc(d.label)} | Capacité graduée ${fmt(d.gradedCapacity)} | Consensus gradué ${fmt(d.gradedConsensus)}" x="${x}" y="${base-d.gradedCapacity*2.6}" width="${b*.28}" height="${d.gradedCapacity*2.6}" fill="#96305e"/><rect class="graphbar" data-detail="${esc(d.label)} | Capacité graduée ${fmt(d.gradedCapacity)} | Consensus gradué ${fmt(d.gradedConsensus)}" x="${x+b*.3}" y="${base-d.gradedConsensus*2.6}" width="${b*.28}" height="${d.gradedConsensus*2.6}" fill="#7777dd"/><text x="${x}" y="${base+18}" font-size="11" transform="rotate(-40 ${x} ${base+18})">${esc(d.code)}</text>`}).join('')}</svg><table><tr><th>Moyennes de la cohorte</th><th>Note Cap</th><th>Note Cons</th></tr>${a.map(d=>`<tr><td>${esc(d.code)}</td><td>${fmt(d.gradedCapacity)}</td><td>${fmt(d.gradedConsensus)}</td></tr>`).join('')}</table>`}
visual=ds=>`<section class="graphs">${graduatedGrid(ds)}<h3>Notes standardisées</h3>${bars([...cohort(ds).a,{label:'Moyenne',code:'Moyenne',capacity:cohort(ds).a.reduce((x,d)=>x+d.capacity,0)/cohort(ds).a.length,consensus:cohort(ds).a.reduce((x,d)=>x+d.consensus,0)/cohort(ds).a.length}])}${cohortChart(ds)}<div class="legend">20–39 : Loin en dessous · 40–59 : En dessous · 60–70 : Moyen · 71–80 : Au-dessus · 81–100 : Bien au-dessus</div></section>`;
bars=(ds,grad=false)=>{let a=ds.filter(d=>d.capacity!=null),w=760,h=430,left=70,top=70,bottom=330,step=620/(a.length||1);if(!a.length)return '<p class="muted">Pas encore de données disponibles.</p>';return `<svg class="chart excel-chart" viewBox="0 0 ${w} ${h}"><rect x="${left}" y="${top}" width="620" height="${bottom-top}" fill="#b7b7b7" stroke="#000"/>${[0,20,40,60,80,100].map(v=>`<line x1="${left}" y1="${bottom-v*2.6}" x2="690" y2="${bottom-v*2.6}" stroke="#eee"/><text x="18" y="${bottom-v*2.6+4}">${v},00</text>`).join('')}<text x="200" y="25" font-size="20" font-weight="bold">Notes Standardisees</text><rect x="210" y="38" width="12" height="12" fill="#8e8def"/><text x="227" y="49">Capacity Score</text><rect x="350" y="38" width="12" height="12" fill="#96305e"/><text x="367" y="49">Consensus Score</text>${a.map((d,i)=>{let x=left+18+i*step,c=grad?d.gradedCapacity:d.capacity,s=grad?d.gradedConsensus:d.consensus;return `<rect class="graphbar" data-detail="${esc(d.label)} | Capacité ${fmt(c)} | Consensus ${fmt(s)}" x="${x}" y="${bottom-c*2.6}" width="${step*.24}" height="${c*2.6}" fill="#8e8def" stroke="#000"/><rect class="graphbar" data-detail="${esc(d.label)} | Capacité ${fmt(c)} | Consensus ${fmt(s)}" x="${x+step*.27}" y="${bottom-s*2.6}" width="${step*.24}" height="${s*2.6}" fill="#96305e" stroke="#000"/><text x="${x}" y="${bottom-c*2.6-4}" font-size="10">${Math.round(c)}</text><text x="${x+step*.27}" y="${bottom-s*2.6-4}" font-size="10">${Math.round(s)}</text><text x="${x}" y="${bottom+22}" font-size="11" transform="rotate(-45 ${x} ${bottom+22})">${esc(d.code||d.label).slice(0,11)}</text>`}).join('')}<text x="275" y="410" font-size="15" font-weight="bold">Domaines de Competence</text></svg>`};
const barsBasic=bars;bars=(ds,grad=false)=>{let a=ds.filter(d=>d.capacity!=null);if(!a.length)return '<p class="muted">Pas encore de données disponibles.</p>';return `<svg class="chart" viewBox="0 0 760 ${70+a.length*46}"><text x="180" y="16" fill="#176b4b">■ Capacité</text><text x="290" y="16" fill="#536271">■ Consensus</text>${a.map((d,n)=>{let y=35+n*46,c=grad?d.gradedCapacity:d.capacity,s=grad?d.gradedConsensus:d.consensus,name=esc(d.label);return `<text x="2" y="${y+12}" font-size="11">${name.slice(0,22)}</text><rect x="180" y="${y}" width="${(c||0)*5}" height="15" fill="#176b4b"><title>${name} — Capacité : ${fmt(c)} — Réponses : ${d.responses??'—'}</title></rect><rect x="180" y="${y+18}" width="${(s||0)*5}" height="15" fill="#536271"><title>${name} — Consensus : ${fmt(s)} — Dispersion : ${fmt(d.dispersion)}</title></rect><text x="${185+(c||0)*5}" y="${y+12}" font-size="10">${fmt(c)}</text><text x="${185+(s||0)*5}" y="${y+30}" font-size="10">${fmt(s)}</text>`}).join('')}</svg>`};
bars=(ds,grad=false)=>{let a=ds.filter(d=>d.capacity!=null);if(!a.length)return '<p class="muted">Pas encore de données disponibles.</p>';return `<svg class="chart" viewBox="0 0 760 ${70+a.length*46}"><text x="180" y="16" fill="#176b4b">■ Capacité</text><text x="290" y="16" fill="#536271">■ Consensus</text>${a.map((d,n)=>{let y=35+n*46,c=grad?d.gradedCapacity:d.capacity,s=grad?d.gradedConsensus:d.consensus,name=esc(d.label),meta=`${name} | Capacité ${fmt(c)} | Consensus ${fmt(s)} | Réponses ${d.responses??'—'} | Dispersion ${fmt(d.dispersion)}`;return `<text x="2" y="${y+12}" font-size="11">${name.slice(0,22)}</text><rect class="graphbar" data-detail="${meta}" x="180" y="${y}" width="${(c||0)*5}" height="15" fill="#176b4b"/><rect class="graphbar" data-detail="${meta}" x="180" y="${y+18}" width="${(s||0)*5}" height="15" fill="#536271"/><text x="${185+(c||0)*5}" y="${y+12}" font-size="10">${fmt(c)}</text><text x="${185+(s||0)*5}" y="${y+30}" font-size="10">${fmt(s)}</text>`}).join('')}</svg>`};
document.addEventListener('pointerover',e=>{let b=e.target.closest?.('.graphbar');if(!b)return;let t=document.querySelector('#chart-tip');if(!t){t=document.createElement('div');t.id='chart-tip';t.className='chart-tip';document.body.appendChild(t)}t.textContent=b.dataset.detail;t.style.display='block'});document.addEventListener('pointermove',e=>{let t=document.querySelector('#chart-tip');if(t){t.style.left=(e.clientX+14)+'px';t.style.top=(e.clientY+14)+'px'}});document.addEventListener('pointerout',e=>{if(e.target.closest?.('.graphbar')){let t=document.querySelector('#chart-tip');if(t)t.style.display='none'}});
function downloadFile(name,text,type='text/csv;charset=utf-8'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function csv(rows){return rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\n')}
async function exportDiagnostic(id){let a=await api('/api/sessions/'+id+'/analysis');let domains=[['Domaine','Capacité standardisée','Consensus standardisé','Capacité graduée','Consensus gradué','Réponses','Niveau'],...a.domains.map(d=>[d.label,fmt(d.capacity),fmt(d.consensus),d.gradedCapacity,d.gradedConsensus,d.responses,level(d.capacity)])];let indicators=[['Domaine','Référence','Capacité','Consensus','Réponses','Manquants'],...a.domains.flatMap(d=>d.indicators.map(i=>[d.label,i.label,fmt(i.capacity),fmt(i.consensus),i.responses,i.missing]))];downloadFile('diagnostic-domaines.csv',csv(domains));setTimeout(()=>downloadFile('diagnostic-indicateurs.csv',csv(indicators)),150)}
const diagnosticExportBase=diagnostic;diagnostic=async id=>{await diagnosticExportBase(id);app.querySelector('.grid')?.insertAdjacentHTML('beforebegin',`<div class="row print-actions"><button class="secondary" onclick="window.print()">Imprimer le diagnostic</button><button class="secondary" onclick="exportDiagnostic('${id}')">Télécharger les CSV</button></div>`)};
const finalSummaryExportBase=finalSummary;finalSummary=async id=>{await finalSummaryExportBase(id);app.querySelector('.card')?.insertAdjacentHTML('beforeend',`<div class="row print-actions"><button class="secondary" onclick="window.print()">Imprimer la synthèse</button><button class="secondary" onclick="exportDiagnostic('${id}')">Télécharger les résultats CSV</button></div>`)};
const diagnosticFormatsBase=diagnostic;diagnostic=async id=>{await diagnosticFormatsBase(id);app.querySelector('.print-actions')?.insertAdjacentHTML('beforeend',`<a href="/api/sessions/${id}/report.xlsx"><button type="button" class="secondary">Télécharger Excel</button></a><a href="/api/sessions/${id}/report.docx"><button type="button" class="secondary">Télécharger Word</button></a><a href="/api/sessions/${id}/report.pdf"><button type="button" class="secondary">Télécharger PDF</button></a>`)};
const finalFormatsBase=finalSummary;finalSummary=async id=>{await finalFormatsBase(id);let a=app.querySelectorAll('.print-actions');a[a.length-1]?.insertAdjacentHTML('beforeend',`<a href="/api/sessions/${id}/report.xlsx"><button type="button" class="secondary">Excel</button></a><a href="/api/sessions/${id}/report.docx"><button type="button" class="secondary">Word</button></a><a href="/api/sessions/${id}/report.pdf"><button type="button" class="secondary">PDF</button></a>`)};

/* Phase qualitative : aucune de ces données ne modifie les scores EPC. */
const statusOptions=['A discuter','Retenu par le groupe','Écarté'];
const statusValue=x=>({'A discuter':'A_DISCUTER','Retenu par le groupe':'RETENU','Écarté':'ECARTE'}[x]||x);
const statusLabel=x=>({'A_DISCUTER':'À discuter','RETENU':'Retenu par le groupe','ECARTE':'Écarté'}[x]||x);
const optionList=(items,value,label,blank='— Aucun —')=>`<option value="">${blank}</option>${items.map(x=>`<option value="${x.id}" ${x.id===value?'selected':''}>${esc(label(x))}</option>`).join('')}`;
async function qualitative(s){return Promise.all([api('/api/sessions/'+s+'/analysis'),api('/api/sessions/'+s+'/qualitative-data')])}
function priorityInfo(a,q,p){let d=a.domains.find(x=>x.id===p.domain_id),i=d?.indicators.find(x=>x.id===p.indicator_id);return {d,i,p}}
async function analysisPriorities(s){let [a,q]=await qualitative(s);app.innerHTML=`<section class="card"><button class="secondary" onclick="diagnostic('${s}')">← Retour au diagnostic</button><h2>Analyse des priorités</h2><p>${esc(a.session.name)} · Participants : ${a.participantCount} · réponses validées : ${a.completedCount} · priorités retenues : ${q.priorities.length}</p>${q.priorities.length?'<p>Les résultats chiffrés sont un rappel ; les constats sont saisis et validés par le groupe.</p>':''}${q.priorities.map(p=>{let x=priorityInfo(a,q,p),an=q.analyses.find(z=>z.priority_id===p.id),n=q.entries.filter(e=>e.priority_id===p.id).length;return `<section class="domain"><h3>${esc(p.domain_label)} — ${esc(p.indicator_code)}</h3><p><b>${esc(p.indicator_label)}</b><br>${esc(p.indicator_description)}</p><p>Capacité ${fmt(x.i?.capacity)} · consensus ${fmt(x.i?.consensus)} · ${level(x.i?.capacity)} · ${n?`${n} élément(s) analysé(s)`:'Analyse à compléter'}</p><button onclick="priorityAnalysis('${s}','${p.id}')">Analyser →</button></section>`}).join('')||'<p>Aucune priorité retenue : revenez au diagnostic pour sélectionner les critères à travailler.</p>'}<div class="row"><button class="secondary" onclick="recommendationsView('${s}')">Recommandations →</button><button class="secondary" onclick="finalSummary('${s}')">Synthèse finale →</button></div></section>`}
function entryTree(entries,parent=''){return entries.filter(e=>(e.parent_id||'')===parent).map(e=>`<li><b>${esc(e.kind)}</b> — ${esc(e.content)} <em>(${esc(statusLabel(e.validation_status))})</em><div class="row"><button class="secondary" onclick="editEntry('${e.id}','${e.session_id}','${e.priority_id}')">Modifier</button><button class="secondary" onclick="newEntry('${e.session_id}','${e.priority_id}','cause','${e.id}')">+ Sous-cause</button><button class="danger" onclick="deleteEntry('${e.id}','${e.session_id}','${e.priority_id}')">Supprimer</button></div>${entryTree(entries,e.id)}</li>`).join('')}
async function priorityAnalysis(s,pid){let [a,q]=await qualitative(s),p=q.priorities.find(x=>x.id===pid),x=priorityInfo(a,q,p),an=q.analyses.find(z=>z.priority_id===pid),e=q.entries.filter(z=>z.priority_id===pid);app.innerHTML=`<section class="card"><button class="secondary" onclick="analysisPriorities('${s}')">← Retour aux priorités</button><h2>${esc(p.domain_label)}</h2><h3>${esc(p.indicator_code)} — ${esc(p.indicator_label)}</h3><p>Capacité : <b>${fmt(x.i?.capacity)}</b> · Consensus : <b>${fmt(x.i?.consensus)}</b></p><form onsubmit="saveProblem(event,'${s}','${pid}','${an?.id||''}')"><label>Quel problème ou constat ressort de ce résultat ?<textarea name="problem">${esc(an?.problem||'')}</textarea></label><button>Enregistrer le constat</button></form><hr><h3>Pourquoi cette situation existe-t-elle ?</h3><button onclick="newEntry('${s}','${pid}','cause')">+ Ajouter une cause</button><ul>${entryTree(e.filter(z=>z.kind==='cause'))||'<li>Analyse à compléter</li>'}</ul><h3>Quelles conséquences cette situation entraîne-t-elle ?</h3><button onclick="newEntry('${s}','${pid}','consequence')">+ Ajouter une conséquence</button><ul>${entryTree(e.filter(z=>z.kind==='consequence'))||'<li>Analyse à compléter</li>'}</ul><h3>Sur quoi peut-on agir ?</h3><button onclick="newEntry('${s}','${pid}','lever')">+ Ajouter un levier</button><ul>${entryTree(e.filter(z=>z.kind==='lever'))||'<li>Analyse à compléter</li>'}</ul><div class="row"><button class="secondary" onclick="analysisPriorities('${s}')">← Priorité précédente / liste</button><button onclick="recommendationsView('${s}','${pid}')">Construire les recommandations →</button></div></section>`}
async function saveProblem(e,s,pid,id){e.preventDefault();await api('/api/sessions/'+s+'/priority-analyses',{method:'POST',body:JSON.stringify({priorityId:pid,problem:new FormData(e.target).get('problem')})});priorityAnalysis(s,pid)}
async function newEntry(s,pid,kind,parent=''){let text=prompt(kind==='cause'?'Cause :':kind==='consequence'?'Conséquence :':'Levier :');if(!text?.trim())return;let type=kind==='cause'?prompt('Type facultatif (Cause, Cause racine potentielle, Facteur interne, Facteur externe, Hypothèse) :')||'':'';await api('/api/sessions/'+s+'/analysis-entries',{method:'POST',body:JSON.stringify({priorityId:pid,parentId:parent,kind,content:text,itemType:type,validationStatus:'A_DISCUTER'})});priorityAnalysis(s,pid)}
async function editEntry(id,s,pid){let q=await api('/api/sessions/'+s+'/qualitative-data'),e=q.entries.find(x=>x.id===id),content=prompt('Modifier le texte :',e?.content||'');if(content===null||!e)return;let status=prompt('Statut : À discuter, Retenu par le groupe ou Écarté',statusLabel(e.validation_status));await api('/api/analysis-entries/'+id,{method:'PUT',body:JSON.stringify({...e,content,validationStatus:statusValue(status)})});priorityAnalysis(s,pid)}
async function deleteEntry(id,s,pid){try{await api('/api/analysis-entries/'+id,{method:'DELETE'});notice('Élément supprimé.')}catch(err){if(confirm(err.message+'\n\nForcer la suppression ?'))await api('/api/analysis-entries/'+id+'?force=1',{method:'DELETE'});else return}priorityAnalysis(s,pid)}
async function recommendationsView(s,selected=''){let [a,q]=await qualitative(s),entries=q.entries.filter(e=>e.validation_status==='RETENU'),recs=q.recommendations;app.innerHTML=`<section class="card"><button class="secondary" onclick="analysisPriorities('${s}')">← Retour aux analyses</button><h2>Recommandations</h2><form onsubmit="saveRecommendationV2(event,'${s}')"><label>Titre *<input name="title" required></label><label>Description / action proposée *<textarea name="description" required></textarea></label><label>Priorité concernée<select name="priorityId">${optionList(q.priorities,selected,x=>x.domain_label+' — '+x.indicator_label)}</select></label><label>Cause retenue<select name="causeId">${optionList(entries.filter(x=>x.kind==='cause'),' ',x=>x.content)}</select></label><label>Levier retenu<select name="leverId">${optionList(entries.filter(x=>x.kind==='lever'),' ',x=>x.content)}</select></label><label>Catégorie<select name="category">${['Formation','Organisation','Gouvernance','Ressources humaines','Ressources financières','Processus','Partenariat','Communication','Équipement / moyens','Autre'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Niveau de priorité<select name="priorityLevel">${['Haute','Moyenne','Basse','Non définie'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Responsable / acteur concerné<input name="owner"></label><label>Échéance<input name="horizon"></label><label>Commentaire<textarea name="comment"></textarea></label><button>Ajouter la recommandation</button></form><h3>Tableau de synthèse</h3><table><tr><th>Recommandation</th><th>Catégorie</th><th>Niveau</th><th>Responsable</th><th>Statut</th><th></th></tr>${recs.map(r=>`<tr><td><b>${esc(r.title)}</b><br>${esc(r.description)}</td><td>${esc(r.category)}</td><td>${esc(r.priority_level)}</td><td>${esc(r.owner||'—')}</td><td>${esc(r.status)}</td><td><button class="secondary" onclick="setRecommendationStatus('${s}','${r.id}')">Statut</button><button class="danger" onclick="deleteRecommendation('${s}','${r.id}')">Supprimer</button></td></tr>`).join('')||'<tr><td colspan="6">Aucune recommandation.</td></tr>'}</table><div class="row"><button onclick="trainingView('${s}')">Besoins / thèmes de formation →</button><button class="secondary" onclick="planView('${s}')">Plan d’action →</button></div></section>`}
async function saveRecommendationV2(e,s){e.preventDefault();await api('/api/sessions/'+s+'/recommendations-v2',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});recommendationsView(s)}
async function setRecommendationStatus(s,id){let status=prompt('Statut : Proposée, Retenue ou Écartée','Proposée');if(!status)return;let q=await api('/api/sessions/'+s+'/qualitative-data'),r=q.recommendations.find(x=>x.id===id);await api('/api/recommendations-v2/'+id,{method:'PUT',body:JSON.stringify({...r,status})});recommendationsView(s)}
async function deleteRecommendation(s,id){try{await api('/api/recommendations-v2/'+id,{method:'DELETE'})}catch(e){if(confirm(e.message+'\n\nForcer la suppression ?'))await api('/api/recommendations-v2/'+id+'?force=1',{method:'DELETE'})}recommendationsView(s)}
async function trainingView(s){let q=await api('/api/sessions/'+s+'/qualitative-data'),formation=q.recommendations.filter(r=>r.category==='Formation');app.innerHTML=`<section class="card"><button class="secondary" onclick="recommendationsView('${s}')">← Retour aux recommandations</button><h2>Besoins / thèmes de formation</h2><p>Les recommandations de catégorie Formation sont reprises automatiquement ; aucun contenu de formation n’est inventé.</p><form onsubmit="saveTraining(event,'${s}')"><label>Intitulé *<input name="title" required></label><label>Besoin auquel il répond<textarea name="needText"></textarea></label><label>Public cible<input name="targetAudience"></label><label>Priorité<select name="priorityLevel"><option>Haute</option><option>Moyenne</option><option>Basse</option><option selected>Non définie</option></select></label><label>Commentaire<textarea name="comment"></textarea></label><button>Ajouter un thème de formation</button></form><h3>Recommandations Formation</h3>${formation.map(r=>`<p><b>${esc(r.title)}</b> — ${esc(r.description)} (${esc(r.status)})</p>`).join('')||'<p>Aucune.</p>'}<h3>Thèmes créés</h3>${q.trainingTopics.map(t=>`<p><b>${esc(t.title)}</b> — ${esc(t.need_text||'—')} <button class="danger" onclick="api('/api/training-topics/${t.id}',{method:'DELETE'}).then(()=>trainingView('${s}'))">Supprimer</button></p>`).join('')||'<p>Aucun.</p>'}<button onclick="planView('${s}')">Plan d’action →</button></section>`}
async function saveTraining(e,s){e.preventDefault();await api('/api/sessions/'+s+'/training-topics',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});trainingView(s)}
async function planView(s){let q=await api('/api/sessions/'+s+'/qualitative-data'),r=q.recommendations.filter(x=>x.status==='Retenue');app.innerHTML=`<section class="card"><button class="secondary" onclick="recommendationsView('${s}')">← Retour aux recommandations</button><h2>Plan d’action</h2><table><tr><th>N°</th><th>Action / recommandation</th><th>Origine</th><th>Responsable</th><th>Échéance</th><th>Priorité</th><th>Statut</th></tr>${r.map((x,n)=>`<tr><td>${n+1}</td><td>${esc(x.title)}</td><td>${esc(x.priority_id||'—')}</td><td>${esc(x.owner||'—')}</td><td>${esc(x.horizon||'—')}</td><td>${esc(x.priority_level)}</td><td>${esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="7">Aucune recommandation retenue.</td></tr>'}</table><button onclick="finalSummary('${s}')">Synthèse finale →</button></section>`}
const diagnosticQualBase=diagnostic;diagnostic=async id=>{await diagnosticQualBase(id);app.querySelector('.card')?.insertAdjacentHTML('beforeend',`<div class="row"><button onclick="analysisPriorities('${id}')">Analyser les priorités →</button></div>`)};
const finalSummaryQualBase=finalSummary;finalSummary=async id=>{await finalSummaryQualBase(id);let [a,q]=await qualitative(id),section=app.querySelector('.card');section?.insertAdjacentHTML('beforeend',`<hr><h2>Analyse des priorités</h2>${q.priorities.map(p=>{let an=q.analyses.find(x=>x.priority_id===p.id),e=q.entries.filter(x=>x.priority_id===p.id&&x.validation_status==='RETENU');return `<section><h3>${esc(p.domain_label)} — ${esc(p.indicator_code)}</h3><p>${esc(p.indicator_label)}</p><p>Capacité ${fmt(priorityInfo(a,q,p).i?.capacity)} · consensus ${fmt(priorityInfo(a,q,p).i?.consensus)}</p><p><b>Constat :</b> ${esc(an?.problem||'Analyse à compléter')}</p><p><b>Causes :</b> ${e.filter(x=>x.kind==='cause').map(x=>esc(x.content)).join(' ; ')||'—'}</p><p><b>Conséquences :</b> ${e.filter(x=>x.kind==='consequence').map(x=>esc(x.content)).join(' ; ')||'—'}</p><p><b>Leviers :</b> ${e.filter(x=>x.kind==='lever').map(x=>esc(x.content)).join(' ; ')||'—'}</p></section>`}).join('')||'<p>Aucune priorité.</p>'}<h2>Recommandations retenues</h2>${q.recommendations.filter(x=>x.status==='Retenue').map(x=>`<p><b>${esc(x.title)}</b> — ${esc(x.description)}</p>`).join('')||'<p>Aucune.</p>'}<h2>Thèmes de formation</h2>${[...q.trainingTopics,...q.recommendations.filter(x=>x.category==='Formation').map(x=>({title:x.title,need_text:x.description}))].map(x=>`<p><b>${esc(x.title)}</b> — ${esc(x.need_text||'—')}</p>`).join('')||'<p>Aucun.</p>'}<p><button class="secondary" onclick="recommendationsView('${id}')">← Retour aux recommandations</button></p>`)};

const moderatorReportBase=moderator;moderator=async id=>{await moderatorReportBase(id);app.querySelector('.card')?.insertAdjacentHTML('beforeend',`<div class="row"><button onclick="finalReport('${id}')">Rapport final</button><button class="secondary" onclick="reportMetadata('${id}')">Informations de l’atelier</button></div>`)};
async function reportMetadata(s){let r=await api('/api/sessions/'+s+'/report-data'),m=r.meta,session=r.analysis.session;app.innerHTML=`<section class="card"><button class="secondary" onclick="moderator('${s}')">← Retour à l’atelier</button><h2>Informations de l’atelier</h2><form onsubmit="saveReportMeta(event,'${s}')"><label>Intitulé de l’atelier *<input name="name" required value="${esc(session.name)}"></label><label>Organisation / structure<input name="organization" value="${esc(session.organization||'')}"></label><label>Lieu<input name="location" value="${esc(session.location||'')}"></label><label>Date<input name="date" value="${esc(session.date||'')}"></label><label>Animateur / facilitateur<input name="facilitator" value="${esc(m.facilitator||'')}"></label><label>Public / groupe concerné<input name="audience" value="${esc(m.audience||'')}"></label><label>Commentaire ou contexte<textarea name="context">${esc(m.context||'')}</textarea></label><label>Conclusion générale de l’atelier<textarea name="conclusion">${esc(m.conclusion||'')}</textarea></label><button>Enregistrer</button></form></section>`}
async function saveReportMeta(e,s){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));await api('/api/sessions/'+s,{method:'PUT',body:JSON.stringify(x)});await api('/api/sessions/'+s+'/report-meta',{method:'POST',body:JSON.stringify(x)});finalReport(s)}
function reportMethodology(t){let scale=Object.entries(t.scale.labels||{}).sort((a,b)=>Number(a[0])-Number(b[0])).map(([n,l])=>`${n} : ${l||'non libellé'}`).join(' · ');return `Chaque participant renseigne les indicateurs selon l’échelle configurée (${t.scale.min}–${t.scale.max} : ${scale||'libellés non renseignés'}). Les réponses sont agrégées par indicateur et par domaine. La capacité exprime la moyenne standardisée sur 100 ; le consensus traduit l’homogénéité des réponses à partir de leur dispersion. Les notes sont ensuite graduées suivant la norme du questionnaire. Les participants sélectionnent collectivement les priorités, puis documentent les causes, conséquences, leviers et recommandations.`}
function reportTable(rows,headers){return `<table><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr>${rows||`<tr><td colspan="${headers.length}">Non renseigné</td></tr>`}</table>`}
async function finalReport(s){let r=await api('/api/sessions/'+s+'/report-data'),a=r.analysis,t=r.template,q=r.qualitative,m=r.meta,g=a.global,ds=a.domains.filter(d=>d.capacity!=null),priorities=q.priorities;let indicatorRows=ds.flatMap(d=>d.indicators.filter(i=>i.capacity!=null).map(i=>({...i,domain:d.label}))),retained=q.entries.filter(x=>x.validation_status==='RETENU'),priorityById=Object.fromEntries(priorities.map(x=>[x.id,x]));let rankings=(list,key,dir=1)=>list.slice().sort((x,y)=>dir*((x[key]??0)-(y[key]??0))).map(x=>`<li>${esc(x.domain||x.label)}${x.domain?' — '+esc(x.label):''} : ${fmt(x[key])}</li>`).join('')||'<li>Non renseigné</li>';app.innerHTML=`<article class="report"><div class="report-actions"><button class="secondary" onclick="moderator('${s}')">← Retour à l’atelier</button><button onclick="window.print()">Imprimer / PDF</button><a href="/api/sessions/${s}/report.xlsx"><button type="button" class="secondary">Télécharger Excel</button></a></div><nav class="report-nav">${['Méthodologie','Participation','Diagnostic global','Domaines','Priorités','Analyses','Recommandations','Formations','Plan d’action','Annexes'].map(x=>`<a href="#${x.replaceAll(' ','-').replaceAll('é','e')}">${x}</a>`).join('')}</nav><section class="report-cover"><h1>DIAGNOSTIC EPC / SENEVAL</h1><h2>${esc(a.session.name)}</h2><p>${esc(a.session.organization||'Non renseigné')}<br>${esc(a.session.location||'Non renseigné')}<br>${esc(a.session.date||'Non renseigné')}</p><p>Participants : ${a.participantCount} · questionnaires validés : ${a.completedCount}${m.facilitator?`<br>Animateur / facilitateur : ${esc(m.facilitator)}`:''}</p></section><section><h2>Contexte</h2><p>${esc(m.context||'Non renseigné')}</p></section><section id="Méthodologie"><h2>Méthodologie</h2><p>${esc(reportMethodology(t))}</p></section><section id="Participation"><h2>Participation</h2><p>Participants enregistrés : ${a.participantCount} · questionnaires validés : ${a.completedCount} · incomplets : ${Math.max(0,a.participantCount-a.completedCount)} · taux de complétion : ${a.participantCount?Math.round(a.completedCount/a.participantCount*100):'—'}%</p></section><section id="Diagnostic-global"><h2>Diagnostic global</h2><div class="grid"><div class="metric">Capacité standardisée <b>${fmt(g.capacity)}</b></div><div class="metric">Consensus standardisé <b>${fmt(g.consensus)}</b></div><div class="metric">Capacité graduée <b>${g.gradedCapacity??'—'}</b></div><div class="metric">Consensus gradué <b>${g.gradedConsensus??'—'}</b></div></div>${visual(ds)}</section><section id="Domaines"><h2>Tableau synthétique des domaines</h2>${reportTable(ds.map(d=>`<tr><td>${esc(d.label)}</td><td>${fmt(d.capacity)}</td><td>${fmt(d.consensus)}</td><td>${d.gradedCapacity??'—'}</td><td>${d.gradedConsensus??'—'}</td><td>${esc(level(d.capacity))}</td><td>${d.responses}</td></tr>`).join(''),['Domaine','Capacité','Consensus','Cap. graduée','Cons. gradué','Niveau','Répondants'])}${ds.map(d=>`<section class="report-domain"><h3>${esc(d.label)}</h3><p>Capacité ${fmt(d.capacity)} · consensus ${fmt(d.consensus)} · notes graduées ${d.gradedCapacity??'—'} / ${d.gradedConsensus??'—'} · ${esc(level(d.capacity))} · ${d.responses} répondant(s)</p>${bars(d.indicators)}${reportTable(d.indicators.map(i=>`<tr><td>${esc(i.code)}</td><td>${esc(i.label)}</td><td>${fmt(i.capacity)}</td><td>${fmt(i.consensus)}</td><td>${i.responses}</td><td>${i.missing}</td></tr>`).join(''),['Référence','Indicateur','Capacité','Consensus','Réponses','Données manquantes'])}</section>`).join('')}</section><section><h2>Lecture des résultats</h2><div class="report-columns"><div><h3>Domaines les plus faibles</h3><ol>${rankings(ds,'capacity',1)}</ol><h3>Indicateurs les plus faibles</h3><ol>${rankings(indicatorRows,'capacity',1)}</ol></div><div><h3>Domaines les plus forts</h3><ol>${rankings(ds,'capacity',-1)}</ol><h3>Indicateurs les plus forts</h3><ol>${rankings(indicatorRows,'capacity',-1)}</ol><h3>Indicateurs à faible consensus</h3><ol>${rankings(indicatorRows,'consensus',1)}</ol></div></div></section><section id="Priorités"><h2>Priorités retenues par les participants</h2>${reportTable(priorities.map(p=>{let d=a.domains.find(x=>x.id===p.domain_id),i=d?.indicators.find(x=>x.id===p.indicator_id);return `<tr><td>${esc(p.domain_label)}</td><td>${esc(p.indicator_code)}</td><td>${esc(p.indicator_label)}</td><td>${fmt(i?.capacity)}</td><td>${fmt(i?.consensus)}</td></tr>`}).join(''),['Domaine','Référence','Indicateur','Capacité','Consensus'])}</section><section id="Analyses"><h2>Analyse qualitative</h2>${priorities.map(p=>{let an=q.analyses.find(x=>x.priority_id===p.id),e=retained.filter(x=>x.priority_id===p.id);return `<section><h3>${esc(p.domain_label)} — ${esc(p.indicator_code)} — ${esc(p.indicator_label)}</h3><p><b>Constat :</b> ${esc(an?.problem||'Analyse non réalisée')}</p><p><b>Causes retenues :</b> ${e.filter(x=>x.kind==='cause').map(x=>esc(x.content)).join(' ; ')||'Non renseigné'}</p><p><b>Conséquences retenues :</b> ${e.filter(x=>x.kind==='consequence').map(x=>esc(x.content)).join(' ; ')||'Non renseigné'}</p><p><b>Leviers retenus :</b> ${e.filter(x=>x.kind==='lever').map(x=>esc(x.content)).join(' ; ')||'Non renseigné'}</p></section>`}).join('')||'<p>Analyse non réalisée.</p>'}</section><section id="Recommandations"><h2>Recommandations retenues</h2>${q.recommendations.filter(x=>x.status==='Retenue').map(x=>{let p=priorityById[x.priority_id];return `<section><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><p>${esc(p?`${p.domain_label} — ${p.indicator_label}`:'Origine non renseignée')} · ${esc(x.category)} · priorité ${esc(x.priority_level)} · ${esc(x.owner||'Responsable non renseigné')} · ${esc(x.horizon||'Échéance non renseignée')}</p></section>`}).join('')||'<p>Aucune recommandation retenue.</p>'}</section><section id="Formations"><h2>Besoins / thèmes de formation</h2>${q.trainingTopics.map(x=>`<p><b>${esc(x.title)}</b> — ${esc(x.need_text||'Non renseigné')} · ${esc(x.target_audience||'Public non renseigné')} · ${esc(x.priority_level)}</p>`).join('')||'<p>Aucun thème de formation retenu.</p>'}</section><section id="Plan-d’action"><h2>Plan d’action</h2>${reportTable(q.recommendations.filter(x=>x.status==='Retenue').map((x,n)=>`<tr><td>${n+1}</td><td>${esc(x.title)}</td><td>${esc(priorityById[x.priority_id]?.indicator_label||'—')}</td><td>${esc(x.owner||'—')}</td><td>${esc(x.horizon||'—')}</td><td>${esc(x.priority_level)}</td><td>${esc(x.status)}</td></tr>`).join(''),['N°','Action / recommandation','Origine','Responsable','Échéance','Priorité','Statut'])}</section><section><h2>Conclusion générale de l’atelier</h2><p>${esc(m.conclusion||'Non renseigné')}</p></section><section id="Annexes"><h2>Annexes</h2><h3>Questionnaire utilisé</h3>${t.domains.map(d=>`<h4>${esc(d.label)}</h4><ul>${d.indicators.filter(i=>i.active).map(i=>`<li>${esc(i.code)} — ${esc(i.label)} : ${esc(i.description)}</li>`).join('')}</ul>`).join('')}<p>Échelle : ${esc(reportMethodology(t).split('. ')[0])}.</p><h3>Éléments encore à discuter</h3>${q.entries.filter(x=>x.validation_status==='A_DISCUTER').map(x=>`<p>${esc(x.kind)} — ${esc(x.content)}</p>`).join('')||'<p>Aucun.</p>'}</section></article>`}
const finalReportRadarBase=finalReport;finalReport=async id=>{await finalReportRadarBase(id);let r=await api('/api/sessions/'+id+'/report-data'),graphs=app.querySelector('.report .graphs');graphs?.insertAdjacentHTML('beforebegin',`<h3>Radar global</h3>${radar(r.analysis.domains.filter(d=>d.capacity!=null))}`)};
